static inline int gcd_int(int a, int b) {
    while (b) {
        int t = a % b;
        a = b;
        b = t;
    }
    return a;
}

void merge_node(Node *dest, const Node *L, const Node *R) {
    if (L->plen == 0) { *dest = *R; return; }
    if (R->plen == 0) { *dest = *L; return; }

    ll cross = 0;
    int bnd = gcd_int(L->sg[0], R->pg[0]);
